package cli_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLICommands(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStdout string
		wantStderr string
	}{
		// Init command
		{"init creates config", []string{"init"}, 0, "Config initialized", ""},
		{"init with path", []string{"init", "--config", "/tmp/test.yaml"}, 0, "Config initialized", ""},

		// Get command
		{"get existing key", []string{"get", "database.host"}, 0, "localhost", ""},
		{"get missing key", []string{"get", "nonexistent"}, 1, "", "key not found"},
		{"get no args", []string{"get"}, 2, "", "usage: get <key>"},

		// Set command
		{"set valid", []string{"set", "app.port", "8080"}, 0, "", ""},
		{"set missing value", []string{"set", "key"}, 2, "", "usage: set <key> <value>"},

		// Delete command
		{"delete existing", []string{"delete", "temp.key"}, 0, "", ""},
		{"delete missing", []string{"delete", "ghost"}, 1, "", "key not found"},

		// Validate command
		{"validate good config", []string{"validate"}, 0, "Config valid", ""},
		{"validate bad config", []string{"validate", "--config", "corrupt.yaml"}, 1, "", "invalid YAML"},

		// List command
		{"list all", []string{"list"}, 0, "database.host=localhost", ""},
		{"list json format", []string{"list", "--format", "json"}, 0, `{"database"`, ""},

		// Flags
		{"quiet suppresses output", []string{"set", "x", "y", "--quiet"}, 0, "", ""},
		{"verbose adds detail", []string{"get", "app", "--verbose"}, 0, "DEBUG:", ""},
		{"unknown command", []string{"bogus"}, 2, "", "unknown command"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			exit := runCLI(tt.args, stdout, stderr)

			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if tt.wantStdout != "" && !bytes.Contains(stdout.Bytes(), []byte(tt.wantStdout)) {
				t.Errorf("stdout = %q, want containing %q", stdout, tt.wantStdout)
			}
			if tt.wantStderr != "" && !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr, tt.wantStderr)
			}
		})
	}
}

func TestFileSystemOperations(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")

	tests := []struct {
		name     string
		setup    func()
		args     []string
		wantExit int
		verify   func(t *testing.T)
	}{
		{
			name:     "init creates file",
			args:     []string{"init", "--config", configPath},
			wantExit: 0,
			verify: func(t *testing.T) {
				if _, err := os.Stat(configPath); os.IsNotExist(err) {
					t.Error("config file not created")
				}
			},
		},
		{
			name:     "set persists to disk",
			setup:    func() { os.WriteFile(configPath, []byte("{}"), 0644) },
			args:     []string{"set", "key", "value", "--config", configPath},
			wantExit: 0,
			verify: func(t *testing.T) {
				data, _ := os.ReadFile(configPath)
				if !bytes.Contains(data, []byte("value")) {
					t.Error("value not persisted")
				}
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.setup != nil {
				tt.setup()
			}
			exit := runCLI(tt.args, nil, nil)
			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if tt.verify != nil {
				tt.verify(t)
			}
		})
	}
}
